import{_ as i,o as t,c as a,ag as s}from"./chunks/framework.ePeAWSvT.js";const k=JSON.parse('{"title":"WeCom AI Bot Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"channels/wecom-ai-bot.md","filePath":"channels/wecom-ai-bot.md","lastUpdated":1773062302000}'),n={name:"channels/wecom-ai-bot.md"};function o(l,e,h,r,p,d){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="wecom-ai-bot-channel-configuration" tabindex="-1">WeCom AI Bot Channel Configuration <a class="header-anchor" href="#wecom-ai-bot-channel-configuration" aria-label="Permalink to &quot;WeCom AI Bot Channel Configuration&quot;">​</a></h1><p>Memoh supports integrating with the Enterprise WeChat intelligent bot platform through the long-lived WebSocket channel model. This is the same Bot ID + Secret style flow used by the official OpenClaw WeCom plugin.</p><h2 id="step-1-create-a-wecom-ai-bot" tabindex="-1">Step 1: Create a WeCom AI Bot <a class="header-anchor" href="#step-1-create-a-wecom-ai-bot" aria-label="Permalink to &quot;Step 1: Create a WeCom AI Bot&quot;">​</a></h2><ol><li>Open the Enterprise WeChat client.</li><li>Go to <strong>Workbench</strong> &gt; <strong>Intelligent Bot</strong>.</li><li>Create a bot in <strong>API mode</strong>.</li><li>Choose the <strong>long connection</strong> access method.</li><li>Copy the generated <strong>Bot ID</strong> and <strong>Secret</strong>.</li></ol><h2 id="step-2-configure-memoh" tabindex="-1">Step 2: Configure Memoh <a class="header-anchor" href="#step-2-configure-memoh" aria-label="Permalink to &quot;Step 2: Configure Memoh&quot;">​</a></h2><ol><li>Open your Bot in the Memoh Web UI.</li><li>Go to the <strong>Channels</strong> tab.</li><li>Click <strong>Add Channel</strong> and select <strong>WeCom AI Bot</strong>.</li><li>Fill in: <ul><li><code>Bot ID</code></li><li><code>Secret</code></li><li><code>WebSocket URL</code> only if Tencent gives you a non-default endpoint</li></ul></li><li>Save and enable the channel.</li></ol><p>By default, Memoh connects to:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wss://openws.work.weixin.qq.com</span></span></code></pre></div><h2 id="step-3-talk-to-the-bot" tabindex="-1">Step 3: Talk to the Bot <a class="header-anchor" href="#step-3-talk-to-the-bot" aria-label="Permalink to &quot;Step 3: Talk to the Bot&quot;">​</a></h2><p>After the channel is enabled, send a message to the Enterprise WeChat bot. Memoh will receive the inbound callback over WebSocket and reply on the same request stream.</p><h2 id="step-4-optional-user-binding" tabindex="-1">Step 4: Optional User Binding <a class="header-anchor" href="#step-4-optional-user-binding" aria-label="Permalink to &quot;Step 4: Optional User Binding&quot;">​</a></h2><p>If you want proactive outbound delivery or stricter identity mapping, create a user binding for this channel with one of:</p><ul><li><code>chatid</code> for a direct chat or group chat target</li><li><code>userid</code> when you only need identity matching</li></ul><p>For proactive outbound delivery, <code>chatid</code> is preferred.</p><h2 id="cli-configuration" tabindex="-1">CLI Configuration <a class="header-anchor" href="#cli-configuration" aria-label="Permalink to &quot;CLI Configuration&quot;">​</a></h2><p>Memoh CLI also supports this channel:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">memoh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bot_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wecom_ai_bot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bot_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">wecom_bot_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secret</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">wecom_secre</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">memoh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wecom_ai_bot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --chat_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chati</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Streaming replies are supported.</li><li>Attachment ingest from inbound messages is supported.</li><li>Proactive outbound send currently requires a <code>chatid</code> target.</li></ul>`,19)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
